import 'dart:convert';
import 'package:projeto_atlas/core/network/atlas_http_client.dart';
import 'package:projeto_atlas/features/animal_reproduction/domain/models/animal_reproduction_data.dart';
import 'package:shared_preferences/shared_preferences.dart';
class AnimalReproductionStorageService { final SharedPreferencesAsync _preferences=SharedPreferencesAsync(); final AtlasHttpClient _http=AtlasHttpClient(); String _n(String v)=>v.trim().toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'),'_'); String _key(String f,String g,String a)=>'atlas_animal_reproduction_${_n(f)}_${_n(g)}_${_n(a)}';
Future<List<AnimalReproductionData>> loadRecords({required String farmName,required String groupName,required String animalId}) async {final k=_key(farmName,groupName,animalId); try{final r=await _http.send('GET','/livestock/animals/$animalId/reproduction');final items=r.asMapList().map(AnimalReproductionData.fromMap).toList();await _preferences.setString(k,jsonEncode(items.map((e)=>e.toMap()).toList()));return items;}catch(_){final raw=await _preferences.getString(k);if(raw==null||raw.isEmpty)return[];try{return (jsonDecode(raw) as List).map((e)=>AnimalReproductionData.fromMap(Map<String,dynamic>.from(e))).toList();}catch(_){return[];}}}
Future<List<AnimalReproductionData>> saveRecords({required String farmName,required String groupName,required String animalId,required List<AnimalReproductionData> records}) async {final k=_key(farmName,groupName,animalId);final out=<AnimalReproductionData>[];for(final record in records){if(record.synced){out.add(record);continue;}try{final r=await _http.send('POST','/livestock/animals/$animalId/reproduction',body:record.toApi());out.add(AnimalReproductionData.fromMap(r.asMap()));}catch(_){out.add(record);}}await _preferences.setString(k,jsonEncode(out.map((e)=>e.toMap()).toList()));return out;} }
